from _lib import *
lesson("cleft-sentences", "Struktury emfatyczne", "Zdania rozszczepione (cleft sentences)", 3,
 "Cleft sentence dzieli jedną informację na dwie części, żeby wyróżnić jeden element. Dwa główne typy: It-cleft (It was Tom who broke the window) – akcentuje osobę, rzecz, czas lub miejsce; Wh-cleft (What I need is a holiday) – akcentuje to, co następuje po 'is/was'. Są też formy: All I want is…, The thing that annoys me is…, The reason why… is that…",
 "Struktury te służą do podkreślania, prostowania nieporozumień i budowania napięcia w wypowiedzi. Na egzaminie C1 występują w Part 4 i świetnie podnoszą ocenę z zakresu struktur w Writing i Speaking.",
 dict(scheme="It + be + wyróżniony element + who/that + reszta zdania  |  What + podmiot + czasownik + be + wyróżniony element", word_order="It was in Paris that we met. / What surprised me was his calm.",
      affirmative=["It was my sister who called.", "What I love about this city is the food.", "All I need is some sleep."],
      negative=["It wasn't the price that put me off.", "What I don't understand is why he left."],
      questions=["Was it you who left the door open?", "Is it the noise that bothers you?"]),
 [X("It was Maria who organised the whole event.", "To Maria zorganizowała całe wydarzenie.", "Wyróżnienie osoby – who."),
  X("It was in 2015 that the company went bankrupt.", "To w 2015 roku firma zbankrutowała.", "Wyróżnienie czasu – that (nie when)."),
  X("It's not the money that matters, it's the principle.", "Nie chodzi o pieniądze, tylko o zasadę.", "Prostowanie: not X … it's Y."),
  X("What I need right now is a cup of coffee.", "Teraz potrzebuję filiżanki kawy.", "Wh-cleft: what + czasownik + is."),
  X("What annoys me most is people talking during films.", "Najbardziej denerwuje mnie, gdy ludzie rozmawiają w kinie.", "What + czasownik (annoys) jako podmiot."),
  X("What she did was call the police.", "Zrobiła to, że zadzwoniła na policję.", "What … did was + bezokolicznik bez to."),
  X("All I wanted was a bit of respect.", "Chciałem tylko trochę szacunku.", "All = jedyna rzecz."),
  X("The reason why I left is that I was bored.", "Odszedłem, ponieważ się nudziłem.", "The reason why … is that (nie: is because w stylu formalnym)."),
  X("The person who helped me most was my teacher.", "Najbardziej pomogła mi moja nauczycielka.", "The person who … was …"),
  X("What happened was that the system crashed.", "Stało się to, że system się zawiesił.", "What happened was that + zdanie."),
  X("It was only when I got home that I noticed the mistake.", "Dopiero w domu zauważyłem błąd.", "It was only when … that = dopiero gdy.")],
 [C("It-cleft vs Wh-cleft", "It-cleft wyróżnia element na początku (It was HIM…). Wh-cleft przenosi nacisk na koniec (What I want is PEACE).", "Do prostowania pomyłek: it-cleft. Do budowania napięcia: wh-cleft."),
  C("who vs that w it-cleft", "Dla ludzi who lub that; dla rzeczy, miejsc i czasu – that.", "It was in June that… (nie: It was in June when…)."),
  C("What I did was + inf vs What I did was to + inf", "Obie formy poprawne; bez 'to' jest częstsze.", "Na egzaminie bezpieczniej bez to.")],
 [W("It was in London where we met.", "It was in London that we met.", "W it-cleft po miejscu/czasie używamy that."),
  W("What I need it is a break.", "What I need is a break.", "Nie dodajemy dodatkowego podmiotu 'it'."),
  W("What she did was she called him.", "What she did was call him.", "Po was – sam bezokolicznik."),
  W("The reason is because I was tired.", "The reason is that I was tired.", "Reason + because to tautologia w stylu formalnym.")],
 ["Po It is/was czas zależy od sytuacji: It is you who are responsible (czasownik zgadza się z wyróżnionym podmiotem).",
  "W liczbie mnogiej after What…: What we need are new ideas (dopuszczalne jest też is).",
  "Forma z przeczeniem: It wasn't until… that… – znaczy to samo co Not until… + inwersja."],
 [dict(en="It is precisely this lack of transparency that worries voters.", pl="Właśnie ten brak przejrzystości niepokoi wyborców.", note="precisely/only/not so much wzmacniają it-cleft."),
  dict(en="What is often overlooked is the cost to the environment.", pl="Często pomija się koszty dla środowiska.", note="What + strona bierna – idealne do esejów."),
  dict(en="What the report fails to mention is who will pay for it.", pl="Raport nie wspomina, kto za to zapłaci.", note="Krytyka w stylu akademickim.")],
 [G("It was Tom ___ broke the window, not me.", ["who", "that"], "Osoba – who lub that."),
  G("It was in Rome ___ they first met.", ["that"], "Miejsce w it-cleft – that."),
  G("___ I really want is a quiet weekend.", ["What", "what"], "Wh-cleft zaczyna się od What."),
  M("What he did was ___ the manager.", ["phone", "phoned", "phoning", "he phoned"], "phone", "Po What … did was – bezokolicznik.", {"phoned": "Forma przeszła jest już w 'did'.", "phoning": "-ing nie pasuje do tej konstrukcji.", "he phoned": "Nie powtarzamy podmiotu."}),
  G("All I need ___ a bit more time.", ["is"], "All = jedna rzecz → is."),
  K("I only realised the truth when I read his letter.", "UNTIL", "It ___ his letter that I realised the truth.", ["was not until I read", "wasn't until I read"], "It was not until … that."),
  K("His arrogance annoys me.", "WHAT", "___ his arrogance.", ["What annoys me is"], "What + czasownik + me + is."),
  E("It was at midnight when the guests left.", ["It was at midnight that the guests left.", "that the guests left"], "Czas w it-cleft – that.")],
 [K("Lack of sleep causes most of my stress.", "IS", "It ___ causes most of my stress.", ["is lack of sleep that", "is lack of sleep which", "is a lack of sleep that"], "It + is + element + that."),
  K("I just want you to be honest.", "ALL", "___ you to be honest.", ["All I want is for", "All I want is"], "All I want is (for) you to be honest."),
  K("We left because the music was too loud.", "REASON", "The ___ that the music was too loud.", ["reason why we left was", "reason we left was"], "The reason (why) … was that."),
  G("What surprised everyone ___ how quickly she recovered.", ["was"], "Wh-cleft + was."),
  M("It's not the cost ___ worries me, it's the time.", ["that", "what", "where", "who"], "that", "Rzecz – that.", {"what": "What nie łączy się z it-cleft.", "where": "Where dotyczy miejsc i nie pasuje tutaj.", "who": "Who odnosi się do ludzi."}),
  T("To mój brat znalazł twoje klucze.", ["It was my brother who found your keys.", "It was my brother that found your keys."], "It was + osoba + who.")])
